def _place(shop, customer_id, items):
    return shop.orders.handle_create({"customer_id": customer_id, "items": items}).body["order_id"]


def test_unknown_customer(api):
    resp = api.insights.handle_order_history("nope")
    assert resp.status == 404
    assert resp.body == {"error": "customer not found"}


def test_no_orders(shop):
    resp = shop.insights.handle_order_history("c1")
    assert resp.status == 200
    assert resp.body == {"customer_id": "c1", "orders": []}


def test_newest_first_with_cancelled_and_totals(shop):
    first = _place(shop, "c2", [{"sku": "LAMP", "quantity": 2}])  # gold: discounted
    second = _place(shop, "c2", [{"sku": "BOOK", "quantity": 1}])
    third = _place(shop, "c2", [{"sku": "PEN", "quantity": 3}])
    _place(shop, "c1", [{"sku": "PEN", "quantity": 1}])
    shop.orders.handle_cancel(second)
    resp = shop.insights.handle_order_history("c2")
    assert resp.status == 200
    assert resp.body["customer_id"] == "c2"
    orders = resp.body["orders"]
    assert [o["order_id"] for o in orders] == [third, second, first]
    assert orders[1]["status"] == "cancelled"
    assert orders[0]["status"] == orders[2]["status"] != "cancelled"
    for o in orders:
        assert o["total_cents"] == shop.orders.handle_get(o["order_id"]).body["total_cents"]
        assert set(o) == {"order_id", "status", "total_cents"}


def test_lifetime_value_unknown_customer(api):
    resp = api.insights.handle_lifetime_value("nope")
    assert resp.status == 404
    assert resp.body == {"error": "customer not found"}


def test_lifetime_value_no_orders(shop):
    resp = shop.insights.handle_lifetime_value("c1")
    assert resp.status == 200
    assert resp.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_excludes_cancelled_and_uses_discounted_totals(shop):
    first = _place(shop, "c2", [{"sku": "LAMP", "quantity": 2}])  # gold: discounted
    second = _place(shop, "c2", [{"sku": "BOOK", "quantity": 1}])
    third = _place(shop, "c2", [{"sku": "PEN", "quantity": 3}])
    _place(shop, "c1", [{"sku": "PEN", "quantity": 1}])
    shop.orders.handle_cancel(second)
    expected = sum(shop.orders.handle_get(i).body["total_cents"] for i in (first, third))
    resp = shop.insights.handle_lifetime_value("c2")
    assert resp.status == 200
    assert resp.body == {"customer_id": "c2", "order_count": 2, "lifetime_value_cents": expected}


def test_top_customers_rejects_bad_limit(shop):
    for bad in (0, -1, True, False, "3", 1.5, None):
        resp = shop.insights.handle_top_customers(bad)
        assert resp.status == 400
        assert resp.body["error"]


def test_top_customers_empty_when_no_value(shop):
    resp = shop.insights.handle_top_customers(5)
    assert resp.status == 200
    assert resp.body == {"customers": []}


def test_top_customers_ranking_ties_exclusions_and_limit(shop):
    for cid, name in (("c3", "Linus"), ("c4", "Zed"), ("c0", "Nobody")):
        shop.customers.handle_register({"customer_id": cid, "name": name, "email": f"{cid}@example.com"})
    _place(shop, "c2", [{"sku": "LAMP", "quantity": 2}])
    _place(shop, "c3", [{"sku": "PEN", "quantity": 1}])
    _place(shop, "c1", [{"sku": "PEN", "quantity": 1}])
    shop.orders.handle_cancel(_place(shop, "c4", [{"sku": "LAMP", "quantity": 1}]))
    ltv = {c: shop.insights.handle_lifetime_value(c).body["lifetime_value_cents"] for c in ("c1", "c2", "c3")}

    resp = shop.insights.handle_top_customers(10)
    assert resp.status == 200
    assert resp.body["customers"] == [
        {"customer_id": "c2", "name": "Grace", "lifetime_value_cents": ltv["c2"]},
        {"customer_id": "c1", "name": "Ada", "lifetime_value_cents": ltv["c1"]},
        {"customer_id": "c3", "name": "Linus", "lifetime_value_cents": ltv["c3"]},
    ]
    assert ltv["c1"] == ltv["c3"]
    assert shop.insights.handle_top_customers(2).body["customers"] == resp.body["customers"][:2]
